SELECT c."Slug", c."IsActive", (c."DeletedAt" IS NOT NULL) AS trashed, count(m."UserId") AS owner_memberships, bool_and(u."EmailConfirmed") AS owner_email_confirmed FROM "Companies" c LEFT JOIN "CompanyMemberships" m ON m."CompanyId"=c."Id" AND m."RoleKey"='owner' LEFT JOIN "AspNetUsers" u ON u."Id"=m."UserId" WHERE c."Slug" IN ('santa','farma','demo3') GROUP BY c."Id" ORDER BY c."Slug";
